package com.worldheatmap;

import java.io.DataInputStream;
import java.io.IOException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import lombok.Getter;

/**
 * A global heatmap in the compact format made by convert_global_heatmaps.py: floor 0 only, one byte per tile per
 * 64x64 region, where 0 means no data and 1..255 is the tile value's log ratio (log(value) / log(max)), quantised.
 * That ratio is all the colour gradient needs, so the full values are never held in memory.
 * <p>
 * File format (gzipped, big-endian):
 * "WHMG", version byte (1), heatmap type (writeUTF), max value (long), region count (int), then per region:
 * region ID (unsigned short), 4096 levels at index (y &amp; 63) * 64 + (x &amp; 63), i.e. rows from the south edge.
 */
class GlobalHeatmap
{
	static final byte[] MAGIC = {'W', 'H', 'M', 'G'};
	static final int FORMAT_VERSION = 1;
	static final int REGION_SIZE = 64;
	static final int TILES_PER_REGION = REGION_SIZE * REGION_SIZE;
	// Instanced areas (POH, raids etc.) are at x >= 6400, which no world map surface shows, so they're not kept
	private static final int MAX_REGION_X = 6400 >> 6;

	@Getter
	private final Heatmap.HeatmapType heatmapType;
	@Getter
	private final long maxValue;
	// Region ID -> 4096 levels
	@Getter
	private final Map<Integer, byte[]> regions;

	private GlobalHeatmap(Heatmap.HeatmapType heatmapType, long maxValue, Map<Integer, byte[]> regions)
	{
		this.heatmapType = heatmapType;
		this.maxValue = maxValue;
		this.regions = Collections.unmodifiableMap(regions);
	}

	/**
	 * Reads a global heatmap from the (already un-gzipped) stream.
	 */
	static GlobalHeatmap read(DataInputStream in, Heatmap.HeatmapType expectedType) throws IOException
	{
		byte[] magic = new byte[MAGIC.length];
		in.readFully(magic);
		for (int i = 0; i < MAGIC.length; i++)
		{
			if (magic[i] != MAGIC[i])
			{
				throw new IOException("Not a global heatmap file");
			}
		}
		int version = in.readUnsignedByte();
		if (version != FORMAT_VERSION)
		{
			throw new IOException("Unsupported global heatmap format version " + version);
		}
		String type = in.readUTF();
		long maxValue = in.readLong();
		int regionCount = in.readInt();
		if (regionCount < 0 || regionCount > 0x10000 || maxValue < 0)
		{
			throw new IOException("Corrupt global heatmap header");
		}

		Map<Integer, byte[]> regions = new HashMap<>();
		byte[] skipped = null;
		for (int i = 0; i < regionCount; i++)
		{
			int regionId = in.readUnsignedShort();
			if ((regionId >> 8) >= MAX_REGION_X)
			{
				if (skipped == null)
				{
					skipped = new byte[TILES_PER_REGION];
				}
				in.readFully(skipped);
				continue;
			}
			byte[] levels = new byte[TILES_PER_REGION];
			in.readFully(levels);
			regions.put(regionId, levels);
		}
		return new GlobalHeatmap(expectedType != null ? expectedType : Heatmap.HeatmapType.valueOf(type), maxValue, regions);
	}

	/**
	 * @return the tile's level (0 = no data, 1..255)
	 */
	int getLevel(int x, int y)
	{
		byte[] levels = regions.get((x >> 6) << 8 | (y >> 6));
		return levels == null ? 0 : levels[(y & 63) * REGION_SIZE + (x & 63)] & 0xff;
	}

	/**
	 * @return the log ratio a level (1..255) stands for
	 */
	static double logRatio(int level)
	{
		return (level - 1) / 254.0;
	}

	/**
	 * @return the approximate tile value a level (1..255) stands for, to within about 3%
	 */
	long approximateValue(int level)
	{
		if (maxValue <= 1)
		{
			return maxValue;
		}
		return Math.round(Math.exp(logRatio(level) * Math.log(maxValue)));
	}
}

package com.worldheatmap;

import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.zip.GZIPInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Downloads, caches and loads the global heatmap for the overlays. Only one is held in memory at a time.
 * <p>
 * Files are cached in the plugin directory and revalidated (by ETag) once per client session per heatmap, so they're
 * only downloaded again when they change. If the server can't be reached, the cached copy is used.
 * {@link #update} must be called from the client thread; loading happens on the executor.
 */
@Slf4j
@Singleton
class GlobalHeatmapLoader
{
	private static final String BASE_URL = "https://raw.githubusercontent.com/GrandTheftWalrus/gtw-runelite-stuff/main/heatmaps/";
	// The global files are a few MB at most; refuse anything unreasonably large
	private static final long MAX_DOWNLOAD_BYTES = 64L * 1024 * 1024;

	enum Status
	{
		NONE,
		LOADING,
		READY,
		// The server has no global data for this heatmap
		UNAVAILABLE,
		ERROR,
	}

	private final WorldHeatmapPlugin plugin;
	private final WorldHeatmapConfig config;
	private final OkHttpClient okHttpClient;
	private final ScheduledExecutorService executor;

	// File names already checked with the server this session, and ones the server doesn't have
	private final Set<String> revalidated = Collections.synchronizedSet(new HashSet<>());
	private final Set<String> unavailable = Collections.synchronizedSet(new HashSet<>());

	private Heatmap.HeatmapType requestedType;
	// Incremented on every new request, so a slow load for a previous request is discarded
	private volatile int generation;
	private volatile GlobalHeatmap heatmap;
	private volatile Status status = Status.NONE;

	@Inject
	GlobalHeatmapLoader(WorldHeatmapPlugin plugin, WorldHeatmapConfig config, OkHttpClient okHttpClient, ScheduledExecutorService executor)
	{
		this.plugin = plugin;
		this.config = config;
		this.okHttpClient = okHttpClient;
		this.executor = executor;
	}

	/**
	 * Loads the selected heatmap's global data if global mode is on, or frees it if not. Call every client tick.
	 */
	void update()
	{
		final boolean anyOverlay = config.showWorldMapOverlay() || config.showSceneOverlay() || config.showMinimapOverlay();
		final Heatmap.HeatmapType wanted = anyOverlay && config.overlayUseGlobalHeatmaps()
			? config.overlayHeatmapType().getHeatmapType() : null;
		if (wanted == requestedType)
		{
			return;
		}

		requestedType = wanted;
		final int thisGeneration = ++generation;
		heatmap = null;
		if (wanted == null)
		{
			status = Status.NONE;
			return;
		}
		status = Status.LOADING;
		executor.execute(() -> load(wanted, thisGeneration));
	}

	/**
	 * @return the loaded global heatmap, or null if none is loaded (see {@link #getStatus})
	 */
	GlobalHeatmap getHeatmap()
	{
		return heatmap;
	}

	Status getStatus()
	{
		return status;
	}

	void clear()
	{
		requestedType = null;
		generation++;
		heatmap = null;
		status = Status.NONE;
	}

	/**
	 * The file names the global data for a heatmap type may be published under, in order of preference.
	 */
	private static List<String> fileNames(Heatmap.HeatmapType type)
	{
		switch (type)
		{
			// Older global data predates splitting damage into NPC and PVP, under the old type names
			case NPC_DAMAGE_TAKEN:
				return Arrays.asList("NPC_DAMAGE_TAKEN.whmg.gz", "DAMAGE_TAKEN.whmg.gz");
			case NPC_DAMAGE_GIVEN:
				return Arrays.asList("NPC_DAMAGE_GIVEN.whmg.gz", "DAMAGE_GIVEN.whmg.gz");
			default:
				return Collections.singletonList(type.name() + ".whmg.gz");
		}
	}

	/**
	 * Loads the first of the type's file names that the server has (or, if it can't be reached, that's cached).
	 */
	private void load(Heatmap.HeatmapType type, int requestGeneration)
	{
		final Filepath dir = plugin.pluginDirectory.join("Global Heatmaps");
		boolean failed = false;

		for (String name : fileNames(type))
		{
			if (unavailable.contains(name))
			{
				continue;
			}
			final Filepath file = dir.joinSegment(name);
			final Filepath etagFile = dir.joinSegment(name + ".etag");

			try
			{
				if (!revalidated.contains(name))
				{
					if (download(BASE_URL + name, dir, file, etagFile) == Status.UNAVAILABLE)
					{
						// Not (or no longer) published, so don't fall back to a stale cached copy either
						unavailable.add(name);
						file.deleteIfExists();
						etagFile.deleteIfExists();
						continue;
					}
					revalidated.add(name);
				}

				if (!file.exists())
				{
					failed = true;
					continue;
				}

				try (InputStream fileIn = file.openInputStream();
					 DataInputStream in = new DataInputStream(new BufferedInputStream(new GZIPInputStream(fileIn, 64 * 1024))))
				{
					final GlobalHeatmap loaded = GlobalHeatmap.read(in, type);
					log.debug("Loaded global {} heatmap from {}: {} regions, max {}", type, name, loaded.getRegions().size(), loaded.getMaxValue());
					finish(requestGeneration, loaded, Status.READY);
					return;
				}
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Failed to load global {} heatmap from {}", type, name, e);
				failed = true;
			}
		}

		finish(requestGeneration, null, failed ? Status.ERROR : Status.UNAVAILABLE);
	}

	private void finish(int requestGeneration, GlobalHeatmap loaded, Status newStatus)
	{
		// Ignore results for a request that's been replaced
		if (requestGeneration == generation)
		{
			heatmap = loaded;
			status = newStatus;
		}
	}

	/**
	 * Downloads the file if the server's copy differs from the cached one.
	 *
	 * @return UNAVAILABLE if the server has no such file, otherwise READY (including when the server couldn't be
	 * reached, in which case any cached copy is used)
	 */
	private Status download(String url, Filepath dir, Filepath file, Filepath etagFile) throws IOException
	{
		final Request.Builder request = new Request.Builder().url(url);
		if (file.exists() && etagFile.exists())
		{
			request.header("If-None-Match", readString(etagFile));
		}

		try (Response response = okHttpClient.newCall(request.build()).execute())
		{
			if (response.code() == 304)
			{
				return Status.READY;
			}
			if (response.code() == 404)
			{
				return Status.UNAVAILABLE;
			}
			final ResponseBody body = response.body();
			if (!response.isSuccessful() || body == null)
			{
				log.warn("Global heatmap download from {} failed with HTTP {}; using any cached copy", url, response.code());
				return Status.READY;
			}

			dir.createDirectories();
			final Filepath temp = dir.createTempFile("global", ".tmp");
			try
			{
				try (InputStream in = body.byteStream(); OutputStream out = temp.openOutputStream())
				{
					final byte[] buffer = new byte[64 * 1024];
					long total = 0;
					int read;
					while ((read = in.read(buffer)) != -1)
					{
						total += read;
						if (total > MAX_DOWNLOAD_BYTES)
						{
							throw new IOException("Global heatmap download from " + url + " is too large");
						}
						out.write(buffer, 0, read);
					}
				}
				temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			finally
			{
				temp.deleteIfExists();
			}

			final String etag = response.header("ETag");
			if (etag != null)
			{
				etagFile.write(etag);
			}
			else
			{
				etagFile.deleteIfExists();
			}
			return Status.READY;
		}
		catch (IOException e)
		{
			if (!file.exists())
			{
				throw e;
			}
			log.warn("Couldn't check for a newer global heatmap at {}; using the cached copy", url, e);
			return Status.READY;
		}
	}

	private static String readString(Filepath file) throws IOException
	{
		try (InputStream in = file.openInputStream())
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8).trim();
		}
	}
}

package com.worldheatmap;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.util.*;
import java.util.Map.Entry;

import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public class Heatmap
{
	@Getter
	private final HashMap<WorldPoint, Long> heatmapHashMap;
	@Getter
	private final static int heatmapVersion = 103;
	@Getter @Setter
	private transient int versionReadFrom = -1;
	@Getter
	private long totalValue = 0;
	@Getter
	private int tileCount = 0;
	@Getter @Setter
	private int gameTimeTicks = 0;

	public static Heatmap fromCSV(BufferedReader reader) throws IOException
	{
		// Read them field variables
		String[] fieldNames = reader.readLine().split(",", -1);
		String[] fieldValues = reader.readLine().split(",", -1);
		Map<String, String> fieldMap = new HashMap<>();
		for (int i = 0; i < fieldNames.length; i++) {
			fieldMap.put(fieldNames[i], fieldValues[i]);
		}
		long userID = Long.parseLong(fieldMap.getOrDefault("userID", "-1"));
		int heatmapVersion = Integer.parseInt(fieldMap.getOrDefault("heatmapVersion", "-1"));
		String allegedHeatmapType = fieldMap.get("heatmapType");
		int gameTimeTicks = Integer.parseInt(fieldMap.getOrDefault("gameTimeTicks", "-1"));
		// The following fields exist only in version 101 and later
		int accountType = Integer.parseInt(fieldMap.getOrDefault("accountType", "-1"));
		int currentCombatLevel = Integer.parseInt(fieldMap.getOrDefault("currentCombatLevel", "-1"));
		// The following fields exist only in version 102 and later
		String seasonalType = fieldMap.getOrDefault("seasonalType", null);

		// Get HeatmapType from field value if legit
		Heatmap.HeatmapType heatmapType;
		try {
			heatmapType = Heatmap.HeatmapType.valueOf(allegedHeatmapType);
		}
		catch (IllegalArgumentException e) {
			log.debug("Heatmap type '{}' is not a valid Heatmap type (at least in this program version). Ignoring...", allegedHeatmapType);
			throw new IOException("Invalid Heatmap type");
		}

		// Make ze Heatmap and set metadata
		Heatmap heatmap = new Heatmap(heatmapType, userID, accountType, seasonalType, currentCombatLevel);
		heatmap.setVersionReadFrom(heatmapVersion);
		heatmap.setGameTimeTicks(gameTimeTicks);

		// Read and load the tile values
		final int[] errorCount = {0}; // Number of parsing errors occurred during read
		reader.lines().forEach(s -> {
			String[] tile = s.split(",");
			try {
				if (tile.length == 3) {
					// x, y, val (pre-V1.6.1)
					heatmap.set(Integer.parseInt(tile[0]), Integer.parseInt(tile[1]), 0, Long.parseLong(tile[2]));
				}
				else if (tile.length == 4) {
					// x, y, z, val
					heatmap.set(Integer.parseInt(tile[0]), Integer.parseInt(tile[1]), Integer.parseInt(tile[2]), Long.parseLong(tile[3]));
				}
				else {
					log.error("Invalid line in heatmap file: {}", s);
					errorCount[0]++;
				}
			} catch (NumberFormatException e) {
				errorCount[0]++;
			}
		});
		if (errorCount[0] != 0) {
			log.error("{} errors occurred during {} heatmap file read.", errorCount[0], heatmapType);
		}

		return heatmap;
	}

	/**
	 * Subtracts the values of the given heatmap from this heatmap, tile by tile.
	 * Negative results are capped at "minimum". Only tiles that exist in
	 * otherHeatmap are iterated through.
	 *
	 * @param otherHeatmap the heatmap to subtract from this heatmap
	 * @param minimum the minimum value that any tile can have after subtraction (e.g. 0 if you don't want negative values)
	 */
	public void subtract(Heatmap otherHeatmap, int minimum)
	{
		for (Entry<WorldPoint, Long> e : otherHeatmap.getEntrySet())
		{
			int x = e.getKey().getX();
			int y = e.getKey().getY();
			int z = e.getKey().getPlane();
			long val = e.getValue();
			this.set(x, y, z, Math.max(this.get(x, y, z) - val, minimum));
		}
	}

	public enum HeatmapType
	{
		TYPE_A("steps"),
		TYPE_B("ticks"),
		XP_GAINED("xp"),
		TELEPORT_PATHS("teles"),
		TELEPORTED_TO("teles"),
		TELEPORTED_FROM("teles"),
		LOOT_VALUE("gp"),
		PLACES_SPOKEN_AT("msgs"),
		RANDOM_EVENT_SPAWNS("spawns"),
		DEATHS("deaths"),
		NPC_DEATHS("deaths"),
		BOB_THE_CAT_SIGHTING("cats"),
		NPC_DAMAGE_TAKEN("dmg"),
		NPC_DAMAGE_GIVEN("dmg"),
		PVP_DAMAGE_GIVEN("dmg"),
		PVP_DAMAGE_TAKEN("dmg"),
		WORLD_HOPS("hops"),
		LOGIN_LOGOUT("logins"),
		TRADES("trades");

		// Plural unit of a tile's value, e.g. "steps"
		private final String unit;

		HeatmapType(String unit)
		{
			this.unit = unit;
		}

		/**
		 * Formats a tile value with its unit, e.g. "1,234 steps" or "1 step".
		 */
		public String formatValue(long value)
		{
			String u = (value == 1 && unit.endsWith("s")) ? unit.substring(0, unit.length() - 1) : unit;
			return java.text.NumberFormat.getIntegerInstance().format(value) + " " + u;
		}

		/**
		 * Display name shown in config lists/dropdowns, e.g. "NPC Damage Taken" (NPC/PVP/XP stay in capitals).
		 * Not used for anything persisted: files, uploads and config storage all use name().
		 */
		@Override
		public String toString()
		{
			StringBuilder sb = new StringBuilder();
			for (String word : name().split("_"))
			{
				if (sb.length() > 0)
				{
					sb.append(' ');
				}
				if (word.equals("NPC") || word.equals("PVP") || word.equals("XP"))
				{
					sb.append(word);
				}
				else
				{
					sb.append(word.charAt(0)).append(word.substring(1).toLowerCase());
				}
			}
			return sb.toString();
		}
	}
	@Getter @Setter
	private long userID = -1;
	@Getter @Setter
	private int accountType = -1;
	@Getter @Setter
	private HeatmapType heatmapType;
	@Getter @Setter
	private int currentCombatLevel = -1;
	@Getter @Setter
	private String seasonalType;

	/**
	 * Constructor for HeatmapNew object with userID and accountType.
	 * @param heatmapType HeatmapType of the heatmap
	 * @param userID User ID associated with the heatmap
	 * @param accountType Account type associated with the heatmap
	 */
	public Heatmap(HeatmapType heatmapType, long userID, int accountType, String seasonalType, int currentCombatLevel)
	{
		this.heatmapType = heatmapType;
		this.heatmapHashMap = new HashMap<>();
		this.userID = userID;
		this.accountType = accountType;
		this.seasonalType = seasonalType;
		this.currentCombatLevel = currentCombatLevel;
	}

	protected Set<Entry<WorldPoint, Long>> getEntrySet()
	{
		return heatmapHashMap.entrySet();
	}

	public void incrementGameTimeTicks()
	{
		this.gameTimeTicks++;
	}

	/**
	 * Increments the heatmap's value at the given location by the amount specified
	 *
	 * @param x      Original RuneScape x-coord
	 * @param y      Original RuneScape y-coord
	 * @param amount Amount to increment the value by
	 */
	protected void increment(int x, int y, int z, long amount)
	{
		set(x, y, z, get(x, y, z) + amount);
	}

	/**
	 * Increments the heatmap's value at the given location by 1
	 *
	 * @param x Original RuneScape x-coord
	 * @param y Original RuneScape y-coord
	 */
	protected void increment(int x, int y, int z)
	{
		set(x, y, z, get(x, y, z) + 1);
	}

	/**
	 * Sets the heatmap's value at the given location to the given value. If the value is 0, the tile is removed from the heatmap. If the value is negative, nothing happens.
	 *
	 * @param newValue New value
	 * @param x        Original RuneScape x-coord
	 * @param y        Original RuneScape y-coord
	 */
	protected void set(int x, int y, int z, long newValue)
	{
		// We don't keep track of negative values
		if (newValue < 0)
		{
			return;
		}

		//Set it & retrieve previous value
		Long oldValue = heatmapHashMap.put(new WorldPoint(x, y, z), newValue);

		//Update numTilesVisited
		if (oldValue == null && newValue > 0)
		{
			tileCount++;
		}
		else if (oldValue != null && newValue == 0)
		{
			tileCount--;
		}

		//Update total value
		if (oldValue == null)
		{
			totalValue += newValue;
		}
		else
		{
			totalValue += (newValue - oldValue);
		}

		// For not keeping track of unstepped-on tiles
		if (newValue == 0)
		{
			heatmapHashMap.remove(new WorldPoint(x, y, z));
		}
	}

	/**
	 * Returns the estimated total memory usage of the heatmap, in bytes, assuming 64 bit JVM and 8-byte alignment. Relatively expensive to run because it has to iterate through the entire hashmap.
	 * @return size in bytes
	 */
	public int estimateSize(){
		int estSize = 0;
		// Get count of values above and below 128
		for (Entry<WorldPoint, Long> e : getEntrySet())
		{
			int entrySize = 32; // 32: 12 bytes for Entry object header, 4 for hash value, 4 and 4 for the key and value references, 4 for the 'next' reference, then extra 4 for 8-byte alignment
			int pointSize = 24; // 24: 12 bytes for WorldPoint object header, then 4 for each of the three int coords
			long val = e.getValue();
			int longSize = (-128 <= val && val <= 127) ? 0 : 24; // 0 or 24: 0 bytes for Entry's ref to pooled Long, or 12 bytes for header, 8 for inner long plus 4 bytes for 8-byte alignment
			estSize += entrySize + pointSize + longSize;
		}

		// HashMap overhead
		estSize += 32; // 32: 12 bytes for HashMap object header, 4 for size, 4 for threshold, 4 for loadFactor, 4 for modCount, 4 for table reference, then extra 4 for 8-byte alignment
		estSize += 4 * heatmapHashMap.size(); // 4 bytes for each reference in the table array (assuming 32-bit references)

		return estSize;
	}

	/**
	 * Returns the heatmap's value at the given game world location. If the tile has not been stepped on, returns 0.
	 *
	 * @param x Heatmap-style x-coord
	 * @param y Heatmap-style y-coord
	 */
	protected long get(int x, int y, int z)
	{
		return heatmapHashMap.getOrDefault(new WorldPoint(x, y, z), 0L);
	}

	/**
	 * Serializes the provided heatmap data to the specified OutputStream in CSV format.
	 */
	protected void toCSV(OutputStreamWriter bos) throws IOException
	{
		// Write them field variables
		bos.write("userID,heatmapVersion,heatmapType,gameTimeTicks,accountType,currentCombatLevel,seasonalType\n");
		bos.write(this.getUserID() +
			"," + getHeatmapVersion() +
			"," + this.getHeatmapType().name() +
			"," + this.getGameTimeTicks() +
			"," + this.getAccountType() +
			"," + this.getCurrentCombatLevel() +
			"," + this.getSeasonalType() + "\n");

		// Write the tile values
		for (Entry<WorldPoint, Long> e : this.getEntrySet()) {
			int x = e.getKey().getX();
			int y = e.getKey().getY();
			int z = e.getKey().getPlane();
			long val = e.getValue();
			bos.write(x + "," + y + "," + z + "," + val + "\n");
		}
	}

}

