import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws heatmap colours on the minimap.
 * Minimap drawing and clipping adapted from skretzo's Invalid Movement plugin (BSD-2-Clause).
 */
class HeatmapMinimapOverlay extends Overlay
{
	private final Client client;
	private final WorldHeatmapConfig config;
	private final HeatmapOverlayCache cache;
	private final SpriteManager spriteManager;

	private BufferedImage minimapSpriteFixed;
	private BufferedImage minimapSpriteResizeable;
	private Shape minimapClipFixed;
	private Shape minimapClipResizeable;
	private Rectangle minimapRectangle = new Rectangle();

	@Inject
	HeatmapMinimapOverlay(Client client, WorldHeatmapConfig config, HeatmapOverlayCache cache, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.cache = cache;
		this.spriteManager = spriteManager;

		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final HeatmapOverlayCache.TileColours tileColours = config.showMinimapOverlay() ? cache.getTileColours() : null;
		if (tileColours == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		final Shape minimapClipArea = getMinimapClipArea();
		if (minimapClipArea == null)
		{
			return null;
		}

		final Shape oldClip = graphics.getClip();
		graphics.setClip(minimapClipArea);
		try
		{
			renderMinimap(graphics, tileColours);
		}
		finally
		{
			graphics.setClip(oldClip);
		}
		return null;
	}

	private void renderMinimap(Graphics2D graphics, HeatmapOverlayCache.TileColours tileColours)
	{
		final LocalPoint playerLocation = client.getLocalPlayer().getLocalLocation();
		final int playerX = playerLocation.getSceneX();
		final int playerY = playerLocation.getSceneY();
		final int radius = config.overlayMinimapRadius() < 0 ? Integer.MAX_VALUE / 2 : config.overlayMinimapRadius();

		final WorldView worldView = client.getTopLevelWorldView();
		final int z = worldView.getPlane();
		final Tile[][] tiles = worldView.getScene().getTiles()[z];

		final int startX = Math.max(playerX - radius, 0);
		final int endX = Math.min(playerX + radius, tiles.length);
		final int startY = Math.max(playerY - radius, 0);
		final int endY = Math.min(playerY + radius, tiles[0].length);

		for (int x = startX; x < endX; x++)
		{
			for (int y = startY; y < endY; y++)
			{
				final Tile tile = tiles[x][y];
				if (tile == null)
				{
					continue;
				}

				final WorldPoint wp = tile.getWorldLocation();
				final Color colour = tileColours.get(wp.getX(), wp.getY(), wp.getPlane());
				if (colour == null)
				{
					continue;
				}

				final Point posOnMinimap = Perspective.localToMinimap(client, tile.getLocalLocation());
				if (posOnMinimap == null)
				{
					continue;
				}

				drawSquare(graphics, posOnMinimap, colour);
			}
		}
	}

	private void drawSquare(Graphics2D graphics, Point center, Color color)
	{
		final int x = center.getX();
		final int y = center.getY();
		final double angle = (client.getCameraYawTarget() & 0x7FF) * UNIT;

		final int width = (int) client.getMinimapZoom();
		final int height = (int) client.getMinimapZoom();

		final int a = (width % 2 == 0) ? 1 : 0;
		final int b = (height % 2 == 0) ? 1 : 2;

		graphics.setColor(color);
		graphics.rotate(angle, x, y);
		graphics.fillRect(x - width / 2 + a, y - height / 2 - b, width, height);
		graphics.rotate(-angle, x, y);
	}

	private Shape getMinimapClipArea()
	{
		Widget minimapWidget = getMinimapDrawWidget();

		if (minimapWidget == null || minimapWidget.isHidden() || !minimapRectangle.equals(minimapRectangle = minimapWidget.getBounds()))
		{
			minimapClipFixed = null;
			minimapClipResizeable = null;
			minimapSpriteFixed = null;
			minimapSpriteResizeable = null;
		}

		if (client.isResized())
		{
			if (minimapClipResizeable != null)
			{
				return minimapClipResizeable;
			}
			if (minimapSpriteResizeable == null)
			{
				minimapSpriteResizeable = spriteManager.getSprite(SpriteID.RESIZE_MAP_MASK, 0);
			}
			if (minimapSpriteResizeable != null)
			{
				return minimapClipResizeable = bufferedImageToPolygon(minimapSpriteResizeable);
			}
			return getMinimapClipAreaSimple();
		}
		if (minimapClipFixed != null)
		{
			return minimapClipFixed;
		}
		if (minimapSpriteFixed == null)
		{
			minimapSpriteFixed = spriteManager.getSprite(SpriteID.FIXED_MAP_MASK, 0);
		}
		if (minimapSpriteFixed != null)
		{
			return minimapClipFixed = bufferedImageToPolygon(minimapSpriteFixed);
		}
		return getMinimapClipAreaSimple();
	}

	private Widget getMinimapDrawWidget()
	{
		if (client.isResized())
		{
			if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1)
			{
				return client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP);
			}
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
		}
		return client.getWidget(InterfaceID.Toplevel.MINIMAP);
	}

	private Shape getMinimapClipAreaSimple()
	{
		Widget minimapDrawArea = getMinimapDrawWidget();

		if (minimapDrawArea == null || minimapDrawArea.isHidden())
		{
			return null;
		}

		Rectangle bounds = minimapDrawArea.getBounds();

		return new Ellipse2D.Double(bounds.getX(), bounds.getY(), bounds.getWidth(), bounds.getHeight());
	}

	private Polygon bufferedImageToPolygon(BufferedImage image)
	{
		int outsideColour = -1;
		int previousColour;
		final int width = image.getWidth();
		final int height = image.getHeight();
		List<java.awt.Point> points = new ArrayList<>();
		for (int y = 0; y < height; y++)
		{
			previousColour = outsideColour;
			for (int x = 0; x < width; x++)
			{
				int colour = image.getRGB(x, y);
				if (x == 0 && y == 0)
				{
					outsideColour = colour;
					previousColour = colour;
				}
				if (colour != outsideColour && previousColour == outsideColour)
				{
					points.add(new java.awt.Point(x, y));
				}
				if ((colour == outsideColour || x == (width - 1)) && previousColour != outsideColour)
				{
					points.add(0, new java.awt.Point(x, y));
				}
				previousColour = colour;
			}
		}
		int offsetX = 0;
		int offsetY = 0;
		Widget minimapDrawWidget = getMinimapDrawWidget();
		if (minimapDrawWidget != null)
		{
			offsetX = minimapDrawWidget.getBounds().x;
			offsetY = minimapDrawWidget.getBounds().y;
		}
		Polygon polygon = new Polygon();
		for (java.awt.Point point : points)
		{
			polygon.addPoint(point.x + offsetX, point.y + offsetY);
		}
		return polygon;
	}
}

package com.worldheatmap;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Holds the heatmap currently shown by the overlays, its value range, and (if the world map overlay is enabled)
 * a 64x64 one-pixel-per-tile image of each region that has data. Refreshed on the client thread once per game tick,
 * which is the same thread that modifies the heatmaps and renders the overlays.
 */
@Slf4j
@Singleton
class HeatmapOverlayCache
{
	static final int REGION_SIZE = 64;
	// How often (in ticks) to recolour after the heatmap's data changes. Config/heatmap swaps apply immediately.
	private static final int REFRESH_TICKS = 5;

	private final WorldHeatmapPlugin plugin;
	private final WorldHeatmapConfig config;
	private final GlobalHeatmapLoader globalLoader;

	// Global heatmap tile colours by level, for the palette settings they were made with
	private Color[] globalPalette;
	private int globalPaletteSensitivity;
	private int globalPaletteAlpha;

	@Getter
	private Heatmap heatmap;
	@Getter
	private long minVal;
	@Getter
	private long maxVal;
	@Getter
	private Map<Integer, BufferedImage> regionImages = Collections.emptyMap();

	private boolean dirty = true;
	private boolean regionImagesBuilt;
	private int lastTileCount;
	private long lastTotalValue;
	private int ticksSinceRefresh;

	@Inject
	HeatmapOverlayCache(WorldHeatmapPlugin plugin, WorldHeatmapConfig config, GlobalHeatmapLoader globalLoader)
	{
		this.plugin = plugin;
		this.config = config;
		this.globalLoader = globalLoader;
	}

	/**
	 * Forces a rebuild on the next tick, e.g. after an overlay config change.
	 */
	/**
	 * Colours for the game scene and minimap overlays' tiles, for one frame.
	 */
	interface TileColours
	{
		/**
		 * @return the tile's colour, or null if it has no data
		 */
		Color get(int x, int y, int plane);
	}

	/**
	 * Gets the tile colours for this frame: from the global heatmap (floor 0 only) in global mode, otherwise from the
	 * player's own. Reads the config once here rather than per tile. Client thread only.
	 *
	 * @return the colours, or null if there's no data to show
	 */
	TileColours getTileColours()
	{
		final int sensitivity = config.heatmapSensitivity();
		final int alpha = Utils.overlayAlpha(config.overlayOpacity());

		if (config.overlayUseGlobalHeatmaps())
		{
			final GlobalHeatmap global = globalLoader.getHeatmap();
			if (global == null)
			{
				return null;
			}
			final Color[] palette = getGlobalPalette(sensitivity, alpha);
			return (x, y, plane) ->
			{
				final int level = plane == 0 ? global.getLevel(x, y) : 0;
				return level == 0 ? null : palette[level];
			};
		}

		final Heatmap local = heatmap;
		if (local == null)
		{
			return null;
		}
		final long min = minVal;
		final long max = maxVal;
		return (x, y, plane) ->
		{
			final long value = local.get(x, y, plane);
			return value <= 0 ? null : Utils.heatmapColor(value, sensitivity, min, max, alpha);
		};
	}

	private Color[] getGlobalPalette(int sensitivity, int alpha)
	{
		if (globalPalette == null || sensitivity != globalPaletteSensitivity || alpha != globalPaletteAlpha)
		{
			final Color[] palette = new Color[256];
			for (int level = 1; level < 256; level++)
			{
				palette[level] = Utils.heatmapColorFromLogRatio(GlobalHeatmap.logRatio(level), sensitivity, alpha);
			}
			globalPalette = palette;
			globalPaletteSensitivity = sensitivity;
			globalPaletteAlpha = alpha;
		}
		return globalPalette;
	}

	void invalidate()
	{
		dirty = true;
	}

	void clear()
	{
		heatmap = null;
		minVal = 0;
		maxVal = 0;
		regionImages = Collections.emptyMap();
		regionImagesBuilt = false;
		dirty = true;
	}

	void onGameTick()
	{
		if (!config.showSceneOverlay() && !config.showMinimapOverlay() && !config.showWorldMapOverlay())
		{
			if (heatmap != null)
			{
				clear();
			}
			return;
		}

		ticksSinceRefresh++;
		Heatmap current = plugin.getLoadedHeatmap(config.overlayHeatmapType().getHeatmapType());
		// In global mode the world map shows the global heatmap instead
		boolean needsRegionImages = config.showWorldMapOverlay() && !config.overlayUseGlobalHeatmaps();
		boolean structuralChange = dirty || current != heatmap || needsRegionImages != regionImagesBuilt;
		boolean dataChanged = current != null &&
			(current.getTileCount() != lastTileCount || current.getTotalValue() != lastTotalValue);

		if (structuralChange || (dataChanged && ticksSinceRefresh >= REFRESH_TICKS))
		{
			rebuild(current, needsRegionImages);
		}
	}

	private void rebuild(Heatmap current, boolean buildRegionImages)
	{
		if (current == null)
		{
			clear();
			dirty = false;
			return;
		}

		try
		{
			long min = Long.MAX_VALUE;
			long max = 0;
			// Values summed across planes per (x, y), since the world map is 2D
			Map<Integer, long[]> regionSums = buildRegionImages ? new HashMap<>() : null;

			for (Map.Entry<WorldPoint, Long> e : current.getEntrySet())
			{
				long val = e.getValue();
				min = Math.min(min, val);
				max = Math.max(max, val);

				if (regionSums != null)
				{
					WorldPoint wp = e.getKey();
					long[] sums = regionSums.computeIfAbsent(wp.getRegionID(), k -> new long[REGION_SIZE * REGION_SIZE]);
					sums[pixelIndex(wp.getX(), wp.getY())] += val;
				}
			}

			heatmap = current;
			minVal = min == Long.MAX_VALUE ? 0 : min;
			maxVal = max;
			regionImages = regionSums != null ? colourRegions(regionSums) : Collections.emptyMap();
			regionImagesBuilt = buildRegionImages;
			lastTileCount = current.getTileCount();
			lastTotalValue = current.getTotalValue();
			ticksSinceRefresh = 0;
			dirty = false;
		}
		catch (ConcurrentModificationException e)
		{
			// The heatmap was modified off the client thread (e.g. while loading); try again next tick
			log.debug("Heatmap changed while building overlay cache, retrying next tick");
		}
	}

	private Map<Integer, BufferedImage> colourRegions(Map<Integer, long[]> regionSums)
	{
		long min = Long.MAX_VALUE;
		long max = 0;
		for (long[] sums : regionSums.values())
		{
			for (long val : sums)
			{
				if (val > 0)
				{
					min = Math.min(min, val);
					max = Math.max(max, val);
				}
			}
		}

		int sensitivity = config.heatmapSensitivity();
		int alpha = Utils.overlayAlpha(config.overlayOpacity());
		Map<Integer, BufferedImage> images = new HashMap<>();
		for (Map.Entry<Integer, long[]> region : regionSums.entrySet())
		{
			long[] sums = region.getValue();
			int[] argb = new int[sums.length];
			for (int i = 0; i < sums.length; i++)
			{
				if (sums[i] > 0)
				{
					argb[i] = Utils.heatmapColor(sums[i], sensitivity, min, max, alpha).getRGB();
				}
			}
			BufferedImage image = new BufferedImage(REGION_SIZE, REGION_SIZE, BufferedImage.TYPE_INT_ARGB);
			image.setRGB(0, 0, REGION_SIZE, REGION_SIZE, argb, 0, REGION_SIZE);
			images.put(region.getKey(), image);
		}
		return images;
	}

	/**
	 * Index of a tile's pixel within its region image. Row 0 is the region's north edge.
	 */
	private static int pixelIndex(int x, int y)
	{
		int px = x & (REGION_SIZE - 1);
		int py = REGION_SIZE - 1 - (y & (REGION_SIZE - 1));
		return py * REGION_SIZE + px;
	}
}

package com.worldheatmap;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.ItemLayer;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Renderable;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Tints scene tiles with their heatmap colour.
 * Scene iteration adapted from skretzo's Invalid Movement plugin (BSD-2-Clause).
 * <p>
 * Overlays always draw on top of the rendered scene, so to make the tiles look like they're on the floor,
 * they're drawn into an offscreen buffer and the screen silhouettes of actors/objects (their projected model
 * triangles) are erased from it before it's composited. The floor is the lowest surface, so anything overlapping a floor tile on screen is in front of it.
 */
class HeatmapSceneOverlay extends Overlay
{
	private static final int LOCAL_TILE_SIZE = Perspective.LOCAL_TILE_SIZE;
	// Used when an object's model height isn't known, so it's still considered as a possible occluder
	private static final int FALLBACK_OBJECT_HEIGHT = 1024;
	private static final int OCCUPANCY_CELL_SIZE = 32;

	private final Client client;
	private final WorldHeatmapConfig config;
	private final HeatmapOverlayCache cache;

	private BufferedImage buffer;
	private int[] bufferPixels;
	// Reused per model for projected vertex positions
	private int[] projectedX = new int[0];
	private int[] projectedY = new int[0];

	@Inject
	HeatmapSceneOverlay(Client client, WorldHeatmapConfig config, HeatmapOverlayCache cache)
	{
		this.client = client;
		this.config = config;
		this.cache = cache;

		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final HeatmapOverlayCache.TileColours tileColours = config.showSceneOverlay() ? cache.getTileColours() : null;
		if (tileColours == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		final WorldView worldView = client.getTopLevelWorldView();
		final List<Polygon> polys = new ArrayList<>();
		final List<Color> colours = new ArrayList<>();
		collectTiles(worldView, tileColours, polys, colours);
		if (polys.isEmpty())
		{
			return null;
		}

		if (!config.overlayUnderObjects())
		{
			drawTiles(graphics, polys, colours);
			return null;
		}

		// Region of the canvas covered by heatmap tiles, and a coarse grid of which parts of it are covered
		final Rectangle canvas = new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		Rectangle dirty = null;
		for (Polygon poly : polys)
		{
			dirty = dirty == null ? poly.getBounds() : dirty.union(poly.getBounds());
		}
		dirty = dirty.intersection(canvas);
		if (dirty.isEmpty())
		{
			return null;
		}
		final Occupancy occupancy = new Occupancy(polys);

		if (buffer == null || buffer.getWidth() != canvas.width || buffer.getHeight() != canvas.height)
		{
			buffer = new BufferedImage(canvas.width, canvas.height, BufferedImage.TYPE_INT_ARGB);
			bufferPixels = ((DataBufferInt) buffer.getRaster().getDataBuffer()).getData();
		}

		final Graphics2D g = buffer.createGraphics();
		try
		{
			g.setRenderingHints(graphics.getRenderingHints());
			g.setComposite(AlphaComposite.Clear);
			g.fill(dirty);
			g.setComposite(AlphaComposite.SrcOver);
			drawTiles(g, polys, colours);
		}
		finally
		{
			g.dispose();
		}

		eraseOccluders(worldView, occupancy, dirty);

		graphics.drawImage(buffer.getSubimage(dirty.x, dirty.y, dirty.width, dirty.height), dirty.x, dirty.y, null);
		return null;
	}

	private void collectTiles(WorldView worldView, HeatmapOverlayCache.TileColours tileColours, List<Polygon> polys, List<Color> colours)
	{
		final LocalPoint playerLocation = client.getLocalPlayer().getLocalLocation();
		final int playerX = playerLocation.getSceneX();
		final int playerY = playerLocation.getSceneY();
		final int radius = config.overlaySceneRadius() < 0 ? Integer.MAX_VALUE / 2 : config.overlaySceneRadius();

		final int z = worldView.getPlane();
		final Tile[][] tiles = worldView.getScene().getTiles()[z];

		final int startX = Math.max(playerX - radius, 0);
		final int endX = Math.min(playerX + radius, tiles.length);
		final int startY = Math.max(playerY - radius, 0);
		final int endY = Math.min(playerY + radius, tiles[0].length);

		for (int x = startX; x < endX; x++)
		{
			for (int y = startY; y < endY; y++)
			{
				final Tile tile = tiles[x][y];
				if (tile == null)
				{
					continue;
				}

				final WorldPoint wp = tile.getWorldLocation();
				final Color colour = tileColours.get(wp.getX(), wp.getY(), wp.getPlane());
				if (colour == null)
				{
					continue;
				}

				final Polygon poly = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());
				if (poly == null)
				{
					continue;
				}

				polys.add(poly);
				colours.add(colour);
			}
		}
	}

	private static void drawTiles(Graphics2D graphics, List<Polygon> polys, List<Color> colours)
	{
		for (int i = 0; i < polys.size(); i++)
		{
			graphics.setColor(colours.get(i));
			graphics.fill(polys.get(i));
		}
	}

	/**
	 * Erases the screen silhouettes of walls, scenery, wall decorations and ground items on the current plane from the
	 * tile buffer. Players and NPCs are included too, since the client adds them to the scene as GameObjects each frame.
	 * Floor decorations (GroundObjects) are left out since they lie flat on the floor.
	 * Positions/orientations follow RuneLite's ModelOutlineRenderer. Projecting models is relatively expensive, so each
	 * object's rough screen bounds are checked against the heatmap tiles first.
	 */
	private void eraseOccluders(WorldView worldView, Occupancy occupancy, Rectangle clip)
	{
		final Tile[][] tiles = worldView.getScene().getTiles()[worldView.getPlane()];
		for (Tile[] column : tiles)
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}

				final GameObject[] gameObjects = tile.getGameObjects();
				if (gameObjects != null)
				{
					for (GameObject object : gameObjects)
					{
						// Multi-tile objects are on every tile they cover; only take them from their SW tile
						if (object == null || !object.getSceneMinLocation().equals(tile.getSceneLocation()))
						{
							continue;
						}
						final Renderable renderable = object.getRenderable();
						if (mayOverlap(object, object.sizeX(), object.sizeY(), modelHeight(renderable), occupancy))
						{
							eraseRenderable(worldView, renderable, object.getX(), object.getY(), object.getZ() - animationHeightOffset(renderable), object.getModelOrientation(), occupancy, clip);
						}
					}
				}

				final WallObject wall = tile.getWallObject();
				if (wall != null && mayOverlap(wall, 1, 1, Math.max(modelHeight(wall.getRenderable1()), modelHeight(wall.getRenderable2())), occupancy))
				{
					eraseRenderable(worldView, wall.getRenderable1(), wall.getX(), wall.getY(), wall.getZ() - animationHeightOffset(wall.getRenderable1()), 0, occupancy, clip);
					eraseRenderable(worldView, wall.getRenderable2(), wall.getX(), wall.getY(), wall.getZ() - animationHeightOffset(wall.getRenderable2()), 0, occupancy, clip);
				}

				final DecorativeObject decoration = tile.getDecorativeObject();
				if (decoration != null && mayOverlap(decoration, 1, 1, Math.max(modelHeight(decoration.getRenderable()), modelHeight(decoration.getRenderable2())), occupancy))
				{
					eraseRenderable(worldView, decoration.getRenderable(), decoration.getX() + decoration.getXOffset(), decoration.getY() + decoration.getYOffset(),
						decoration.getZ() - animationHeightOffset(decoration.getRenderable()), 0, occupancy, clip);
					eraseRenderable(worldView, decoration.getRenderable2(), decoration.getX() + decoration.getXOffset2(), decoration.getY() + decoration.getYOffset2(),
						decoration.getZ() - animationHeightOffset(decoration.getRenderable2()), 0, occupancy, clip);
				}

				final ItemLayer items = tile.getItemLayer();
				if (items != null)
				{
					int height = items.getHeight() + modelHeight(items.getBottom()) + modelHeight(items.getMiddle()) + modelHeight(items.getTop());
					if (mayOverlap(items, 1, 1, height, occupancy))
					{
						final int z = items.getZ() - items.getHeight();
						eraseRenderable(worldView, items.getBottom(), items.getX(), items.getY(), z, 0, occupancy, clip);
						eraseRenderable(worldView, items.getMiddle(), items.getX(), items.getY(), z, 0, occupancy, clip);
						eraseRenderable(worldView, items.getTop(), items.getX(), items.getY(), z, 0, occupancy, clip);
					}
				}
			}
		}
	}

	private static int animationHeightOffset(Renderable renderable)
	{
		return renderable == null ? 0 : renderable.getAnimationHeightOffset();
	}

	/**
	 * Projects a renderable's model and clears the pixels of its visible faces from the tile buffer.
	 * Faces are skipped the same way RuneLite's ModelOutlineRenderer skips them: behind the camera, (nearly) fully
	 * transparent, or back-facing.
	 */
	private void eraseRenderable(WorldView worldView, Renderable renderable, int x, int y, int z, int orientation, Occupancy occupancy, Rectangle clip)
	{
		if (renderable == null)
		{
			return;
		}
		final Model model = renderable instanceof Model ? (Model) renderable : renderable.getModel();
		if (model == null)
		{
			return;
		}

		final int vertexCount = model.getVerticesCount();
		if (projectedX.length < vertexCount)
		{
			projectedX = new int[vertexCount];
			projectedY = new int[vertexCount];
		}
		// Note the Y/Z swap: model Y is height, matching ModelOutlineRenderer's call
		Perspective.modelToCanvas(client, worldView, vertexCount, x, y, z, orientation,
			model.getVerticesX(), model.getVerticesZ(), model.getVerticesY(), projectedX, projectedY);

		// Skip the faces entirely if the projected model doesn't reach any heatmap tile
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int maxY = Integer.MIN_VALUE;
		for (int i = 0; i < vertexCount; i++)
		{
			if (projectedY[i] == Integer.MIN_VALUE)
			{
				continue;
			}
			minX = Math.min(minX, projectedX[i]);
			maxX = Math.max(maxX, projectedX[i]);
			minY = Math.min(minY, projectedY[i]);
			maxY = Math.max(maxY, projectedY[i]);
		}
		if (minX > maxX || !occupancy.intersects(new Rectangle(minX, minY, maxX - minX, maxY - minY)))
		{
			return;
		}

		final int faceCount = model.getFaceCount();
		final int[] indices1 = model.getFaceIndices1();
		final int[] indices2 = model.getFaceIndices2();
		final int[] indices3 = model.getFaceIndices3();
		final byte[] transparencies = model.getFaceTransparencies();
		for (int f = 0; f < faceCount; f++)
		{
			final int a = indices1[f];
			final int b = indices2[f];
			final int c = indices3[f];
			if (projectedY[a] == Integer.MIN_VALUE || projectedY[b] == Integer.MIN_VALUE || projectedY[c] == Integer.MIN_VALUE)
			{
				continue;
			}
			if (transparencies != null && (transparencies[f] & 0xff) >= 254)
			{
				continue;
			}
			final int x1 = projectedX[a];
			final int y1 = projectedY[a];
			final int x2 = projectedX[b];
			final int y2 = projectedY[b];
			final int x3 = projectedX[c];
			final int y3 = projectedY[c];
			// Back-facing
			if ((y2 - y1) * (x3 - x2) - (x2 - x1) * (y3 - y2) <= 0)
			{
				continue;
			}
			clearTriangle(clip, x1, y1, x2, y2, x3, y3);
		}
	}

	/**
	 * Clears (makes transparent) the buffer pixels covered by a triangle, within clip. Rounds outwards, so it may
	 * clear up to a pixel extra around the edges, which is fine for hiding the floor behind a model.
	 */
	private void clearTriangle(Rectangle clip, int x1, int y1, int x2, int y2, int x3, int y3)
	{
		// Sort the vertices by y
		int t;
		if (y1 > y2)
		{
			t = x1; x1 = x2; x2 = t;
			t = y1; y1 = y2; y2 = t;
		}
		if (y1 > y3)
		{
			t = x1; x1 = x3; x3 = t;
			t = y1; y1 = y3; y3 = t;
		}
		if (y2 > y3)
		{
			t = x2; x2 = x3; x3 = t;
			t = y2; y2 = y3; y3 = t;
		}

		final int clipBottom = clip.y + clip.height - 1;
		final int clipRight = clip.x + clip.width - 1;
		if (y3 < clip.y || y1 > clipBottom || y1 == y3)
		{
			return;
		}

		final int stride = buffer.getWidth();
		final int yStart = Math.max(y1, clip.y);
		final int yEnd = Math.min(y3, clipBottom);
		for (int y = yStart; y <= yEnd; y++)
		{
			// Long edge (1 to 3) and whichever short edge spans this row
			final double xLong = x1 + (double) (x3 - x1) * (y - y1) / (y3 - y1);
			final double xShort;
			if (y < y2)
			{
				xShort = x1 + (double) (x2 - x1) * (y - y1) / (y2 - y1);
			}
			else
			{
				xShort = y3 == y2 ? x2 : x2 + (double) (x3 - x2) * (y - y2) / (y3 - y2);
			}

			final int left = Math.max(clip.x, (int) Math.floor(Math.min(xLong, xShort)));
			final int right = Math.min(clipRight, (int) Math.ceil(Math.max(xLong, xShort)));
			if (left <= right)
			{
				final int row = y * stride;
				Arrays.fill(bufferPixels, row + left, row + right + 1, 0);
			}
		}
	}

	private static int modelHeight(Renderable renderable)
	{
		return renderable == null ? 0 : Math.max(renderable.getModelHeight(), 0);
	}

	/**
	 * Cheap check of whether an object could overlap any heatmap tile on screen, by projecting the corners of a box
	 * around it (its footprint, from its base up to its model height).
	 */
	private boolean mayOverlap(TileObject object, int sizeX, int sizeY, int height, Occupancy occupancy)
	{
		final LocalPoint lp = object.getLocalLocation();
		if (lp == null)
		{
			return false;
		}

		final int boxHeight = height > 0 ? height + LOCAL_TILE_SIZE / 2 : FALLBACK_OBJECT_HEIGHT;
		final int halfX = sizeX * LOCAL_TILE_SIZE / 2;
		final int halfY = sizeY * LOCAL_TILE_SIZE / 2;
		final int baseZ = object.getZ();

		Rectangle bounds = null;
		for (int dx = -halfX; dx <= halfX; dx += 2 * halfX)
		{
			for (int dy = -halfY; dy <= halfY; dy += 2 * halfY)
			{
				for (int dz = 0; dz >= -boxHeight; dz -= boxHeight)
				{
					final Point p = Perspective.localToCanvas(client, lp.getX() + dx, lp.getY() + dy, baseZ + dz);
					if (p == null)
					{
						continue;
					}
					if (bounds == null)
					{
						bounds = new Rectangle(p.getX(), p.getY(), 0, 0);
					}
					else
					{
						bounds.add(p.getX(), p.getY());
					}
				}
			}
		}
		// If no corner projects (e.g. partly behind the camera), fall back to computing the real shape
		return bounds == null || occupancy.intersects(bounds);
	}

	/**
	 * Coarse screen-space grid of which cells are covered by heatmap tile polygons' bounds.
	 */
	private static class Occupancy
	{
		private final Rectangle area;
		private final int cols;
		private final int rows;
		private final boolean[] cells;

		Occupancy(List<Polygon> polys)
		{
			Rectangle union = null;
			for (Polygon poly : polys)
			{
				union = union == null ? poly.getBounds() : union.union(poly.getBounds());
			}
			area = union;
			cols = area.width / OCCUPANCY_CELL_SIZE + 1;
			rows = area.height / OCCUPANCY_CELL_SIZE + 1;
			cells = new boolean[cols * rows];
			for (Polygon poly : polys)
			{
				final Rectangle b = poly.getBounds();
				for (int cx = col(b.x); cx <= col(b.x + b.width); cx++)
				{
					for (int cy = row(b.y); cy <= row(b.y + b.height); cy++)
					{
						cells[cy * cols + cx] = true;
					}
				}
			}
		}

		boolean intersects(Rectangle r)
		{
			if (!area.intersects(r) && !area.contains(r.x, r.y))
			{
				return false;
			}
			for (int cx = col(r.x); cx <= col(r.x + r.width); cx++)
			{
				for (int cy = row(r.y); cy <= row(r.y + r.height); cy++)
				{
					if (cells[cy * cols + cx])
					{
						return true;
					}
				}
			}
			return false;
		}

		private int col(int x)
		{
			return Math.max(0, Math.min(cols - 1, (x - area.x) / OCCUPANCY_CELL_SIZE));
		}

		private int row(int y)
		{
			return Math.max(0, Math.min(rows - 1, (y - area.y) / OCCUPANCY_CELL_SIZE));
		}
	}
}

package com.worldheatmap;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.image.BufferedImage;
import java.awt.image.DataBuffer;
import java.awt.image.DataBufferByte;
import java.awt.image.IndexColorModel;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.api.worldmap.WorldMapData;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws the whole heatmap on the world map, using the per-region images from HeatmapOverlayCache, plus a tooltip
 * with the hovered tile's value and a box with the hovered tile's coordinates.
 * World map clipping adapted from skretzo's Invalid Movement plugin (BSD-2-Clause).
 */
class HeatmapWorldMapOverlay extends Overlay
{
	private static final int REGION_SIZE = HeatmapOverlayCache.REGION_SIZE;
	private static final int COORDS_MARGIN = 4;
	private static final int COORDS_PADDING = 4;

	private final Client client;
	private final WorldHeatmapConfig config;
	private final HeatmapOverlayCache cache;
	private final TooltipManager tooltipManager;
	private final WorldMapHeatmapList selectorList;
	private final GlobalHeatmapLoader globalLoader;

	// Images wrapping the loaded global heatmap's region bytes, for the palette they were made with
	private GlobalHeatmap globalImagesHeatmap;
	private int globalImagesSensitivity;
	private int globalImagesAlpha;
	private Map<Integer, BufferedImage> globalImages = new HashMap<>();

	@Inject
	HeatmapWorldMapOverlay(Client client, WorldHeatmapConfig config, HeatmapOverlayCache cache, TooltipManager tooltipManager,
		WorldMapHeatmapList selectorList, GlobalHeatmapLoader globalLoader)
	{
		this.client = client;
		this.config = config;
		this.cache = cache;
		this.tooltipManager = tooltipManager;
		this.selectorList = selectorList;
		this.globalLoader = globalLoader;

		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Worldmap.MAP_CONTAINER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showWorldMapOverlay())
		{
			return null;
		}

		final Widget mapView = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		final WorldMap worldMap = client.getWorldMap();
		if (mapView == null || mapView.isHidden() || worldMap == null)
		{
			return null;
		}

		final Rectangle bounds = mapView.getBounds();
		final float pixelsPerTile = worldMap.getWorldMapZoom();
		final Point position = worldMap.getWorldMapPosition();
		final WorldMapData mapData = worldMap.getWorldMapData();
		if (bounds == null || pixelsPerTile <= 0 || position == null || mapData == null)
		{
			return null;
		}

		// Same projection as WorldMapOverlay.mapWorldPointToGraphicsPoint, but for tile edges rather than centres
		final int widthInTiles = (int) Math.ceil(bounds.getWidth() / pixelsPerTile);
		final int heightInTiles = (int) Math.ceil(bounds.getHeight() / pixelsPerTile);
		final int westTile = position.getX() - widthInTiles / 2;
		final int southTile = position.getY() - heightInTiles / 2;
		final Area mapClipArea = getWorldMapClipArea(bounds);

		// Global region images' rows run from the south, so they're drawn flipped
		final boolean global = config.overlayUseGlobalHeatmaps();
		final GlobalHeatmap globalHeatmap = global ? globalLoader.getHeatmap() : null;
		final Map<Integer, BufferedImage> regionImages = global ? getGlobalImages(globalHeatmap) : cache.getRegionImages();
		if (!regionImages.isEmpty())
		{
			drawRegions(graphics, regionImages, global, mapClipArea, bounds, pixelsPerTile, westTile, widthInTiles, southTile, heightInTiles, mapData);
		}

		// Tile under the mouse, if it's over the visible part of the map
		final Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !mapClipArea.contains(mouse.getX(), mouse.getY()) || selectorList.isOverList(mouse.getX(), mouse.getY()))
		{
			return null;
		}
		final int hoveredX = westTile + (int) Math.floor((mouse.getX() - bounds.x) / pixelsPerTile);
		final int hoveredY = southTile + (int) Math.floor((bounds.y + bounds.height - mouse.getY()) / pixelsPerTile);
		if (!mapData.surfaceContainsPosition(hoveredX, hoveredY))
		{
			return null;
		}

		if (global)
		{
			addGlobalValueTooltip(globalHeatmap, hoveredX, hoveredY);
		}
		else
		{
			addValueTooltip(hoveredX, hoveredY);
		}
		drawCoordinates(graphics, bounds, hoveredX + ", " + hoveredY);
		return null;
	}

	private void drawRegions(Graphics2D graphics, Map<Integer, BufferedImage> regionImages, boolean flipped, Area mapClipArea, Rectangle bounds,
		float pixelsPerTile, int westTile, int widthInTiles, int southTile, int heightInTiles, WorldMapData mapData)
	{
		final int minRegionX = (westTile - 1) >> 6;
		final int maxRegionX = (westTile + widthInTiles + 1) >> 6;
		final int minRegionY = (southTile - 1) >> 6;
		final int maxRegionY = (southTile + heightInTiles + 1) >> 6;

		final Shape oldClip = graphics.getClip();
		final Object oldInterpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setClip(mapClipArea);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		try
		{
			for (int rx = minRegionX; rx <= maxRegionX; rx++)
			{
				for (int ry = minRegionY; ry <= maxRegionY; ry++)
				{
					final BufferedImage image = regionImages.get((rx << 8) | ry);
					if (image == null)
					{
						continue;
					}

					final int baseX = rx << 6;
					final int baseY = ry << 6;
					if (!isOnDisplayedSurface(mapData, baseX, baseY))
					{
						continue;
					}

					final int left = Math.round(bounds.x + (baseX - westTile) * pixelsPerTile);
					final int right = Math.round(bounds.x + (baseX + REGION_SIZE - westTile) * pixelsPerTile);
					final int top = Math.round(bounds.y + bounds.height - (baseY + REGION_SIZE - southTile) * pixelsPerTile);
					final int bottom = Math.round(bounds.y + bounds.height - (baseY - southTile) * pixelsPerTile);

					if (flipped)
					{
						graphics.drawImage(image, left, top, right, bottom, 0, REGION_SIZE, REGION_SIZE, 0, null);
					}
					else
					{
						graphics.drawImage(image, left, top, right - left, bottom - top, null);
					}
				}
			}
		}
		finally
		{
			graphics.setClip(oldClip);
			if (oldInterpolation != null)
			{
				graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterpolation);
			}
		}
	}

	/**
	 * Shows the hovered tile's heatmap value, summed across planes like the drawn colours.
	 */
	private void addValueTooltip(int x, int y)
	{
		final Heatmap heatmap = cache.getHeatmap();
		if (heatmap == null)
		{
			return;
		}

		long value = 0;
		for (int plane = 0; plane < 4; plane++)
		{
			value += heatmap.get(x, y, plane);
		}
		if (value > 0)
		{
			tooltipManager.add(new Tooltip(heatmap.getHeatmapType().formatValue(value)));
		}
	}

	/**
	 * Shows the hovered tile's approximate global value. Global data is floor 0 only.
	 */
	private void addGlobalValueTooltip(GlobalHeatmap heatmap, int x, int y)
	{
		final int level = heatmap == null ? 0 : heatmap.getLevel(x, y);
		if (level > 0)
		{
			final long value = roundToSignificantFigures(heatmap.approximateValue(level), 3);
			tooltipManager.add(new Tooltip("~" + heatmap.getHeatmapType().formatValue(value) + " (global)"));
		}
	}

	private static long roundToSignificantFigures(long value, int figures)
	{
		if (value <= 0)
		{
			return value;
		}
		final int digits = (int) Math.floor(Math.log10(value)) + 1;
		if (digits <= figures)
		{
			return value;
		}
		final long scale = (long) Math.pow(10, digits - figures);
		return Math.round((double) value / scale) * scale;
	}

	/**
	 * Images for each of the global heatmap's regions, wrapping its bytes directly with a 256-colour palette
	 * (level 0 transparent), so they take no extra memory beyond the image objects. Changing the sensitivity or
	 * opacity only needs a new palette.
	 */
	private Map<Integer, BufferedImage> getGlobalImages(GlobalHeatmap heatmap)
	{
		if (heatmap == null)
		{
			globalImagesHeatmap = null;
			globalImages = new HashMap<>();
			return globalImages;
		}

		final int sensitivity = config.heatmapSensitivity();
		final int alpha = Utils.overlayAlpha(config.overlayOpacity());
		if (heatmap == globalImagesHeatmap && sensitivity == globalImagesSensitivity && alpha == globalImagesAlpha)
		{
			return globalImages;
		}

		final int[] palette = new int[256];
		for (int level = 1; level < 256; level++)
		{
			palette[level] = Utils.heatmapColorFromLogRatio(GlobalHeatmap.logRatio(level), sensitivity, alpha).getRGB();
		}
		final IndexColorModel colorModel = new IndexColorModel(8, 256, palette, 0, true, -1, DataBuffer.TYPE_BYTE);

		final Map<Integer, BufferedImage> images = new HashMap<>();
		for (Map.Entry<Integer, byte[]> region : heatmap.getRegions().entrySet())
		{
			final DataBufferByte data = new DataBufferByte(region.getValue(), region.getValue().length);
			final WritableRaster raster = Raster.createInterleavedRaster(data, REGION_SIZE, REGION_SIZE, REGION_SIZE, 1, new int[]{0}, null);
			images.put(region.getKey(), new BufferedImage(colorModel, raster, false, null));
		}

		globalImagesHeatmap = heatmap;
		globalImagesSensitivity = sensitivity;
		globalImagesAlpha = alpha;
		globalImages = images;
		return images;
	}

	/**
	 * Draws a small box with the hovered coordinates in the bottom-left corner of the map, moved up above the
	 * overview map if that's open and in the way.
	 */
	private void drawCoordinates(Graphics2D graphics, Rectangle bounds, String text)
	{
		final FontMetrics metrics = graphics.getFontMetrics();
		final int width = metrics.stringWidth(text) + 2 * COORDS_PADDING;
		final int height = metrics.getHeight() + 2 * COORDS_PADDING;
		final Rectangle box = new Rectangle(bounds.x + COORDS_MARGIN, bounds.y + bounds.height - height - COORDS_MARGIN, width, height);

		final Widget overview = client.getWidget(InterfaceID.Worldmap.OVERVIEW_CONTAINER);
		if (overview != null && !overview.isHidden() && overview.getBounds().intersects(box))
		{
			box.y = overview.getBounds().y - height - COORDS_MARGIN;
		}

		graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		graphics.fill(box);

		final int textX = box.x + COORDS_PADDING;
		final int textY = box.y + COORDS_PADDING + metrics.getAscent();
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, textX + 1, textY + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, textX, textY);
	}

	/**
	 * Whether any part of the region belongs to the map surface currently shown (e.g. the main surface vs. a dungeon map)
	 */
	private static boolean isOnDisplayedSurface(WorldMapData mapData, int baseX, int baseY)
	{
		final int last = REGION_SIZE - 1;
		return mapData.surfaceContainsPosition(baseX + REGION_SIZE / 2, baseY + REGION_SIZE / 2)
			|| mapData.surfaceContainsPosition(baseX, baseY)
			|| mapData.surfaceContainsPosition(baseX + last, baseY)
			|| mapData.surfaceContainsPosition(baseX, baseY + last)
			|| mapData.surfaceContainsPosition(baseX + last, baseY + last);
	}

	private Area getWorldMapClipArea(Rectangle baseRectangle)
	{
		final Widget overview = client.getWidget(InterfaceID.Worldmap.OVERVIEW_CONTAINER);
		final Widget surfaceSelector = client.getWidget(InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0);

		Area clipArea = new Area(baseRectangle);

		if (overview != null && !overview.isHidden())
		{
			clipArea.subtract(new Area(overview.getBounds()));
		}

		if (surfaceSelector != null && !surfaceSelector.isHidden())
		{
			clipArea.subtract(new Area(surfaceSelector.getBounds()));
		}

		return clipArea;
	}
}

package com.worldheatmap;

/**
 * Choices for which heatmap the overlays show, i.e. every HeatmapType plus NONE.
 * Kept separate from HeatmapType so NONE doesn't show up as a choice in the enabled heatmaps list.
 * Constant names match HeatmapType's, so a stored overlayHeatmapType value maps straight across.
 */
public enum OverlayHeatmap
{
	NONE,
	TYPE_A,
	TYPE_B,
	XP_GAINED,
	TELEPORT_PATHS,
	TELEPORTED_TO,
	TELEPORTED_FROM,
	LOOT_VALUE,
	PLACES_SPOKEN_AT,
	RANDOM_EVENT_SPAWNS,
	DEATHS,
	NPC_DEATHS,
	BOB_THE_CAT_SIGHTING,
	NPC_DAMAGE_TAKEN,
	NPC_DAMAGE_GIVEN,
	PVP_DAMAGE_GIVEN,
	PVP_DAMAGE_TAKEN,
	WORLD_HOPS,
	LOGIN_LOGOUT,
	TRADES;

	/**
	 * @return the corresponding heatmap type, or null for NONE
	 */
	public Heatmap.HeatmapType getHeatmapType()
	{
		return this == NONE ? null : Heatmap.HeatmapType.valueOf(name());
	}

	public static OverlayHeatmap of(Heatmap.HeatmapType type)
	{
		return type == null ? NONE : valueOf(type.name());
	}

	@Override
	public String toString()
	{
		return this == NONE ? "None" : getHeatmapType().toString();
	}
}

package com.worldheatmap;

import java.awt.Color;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Constants;
import net.runelite.api.Point;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
public class Utils
{

	/**
	 * Serializes heatmap as CSV, zips it, and then uploads it to HEATMAP_SITE_API_ENDPOINT using OkHttpClient.
	 *
	 * @param heatmaps
	 * @return Whether the upload was successful
	 */
	static boolean uploadHeatmaps(Map<Heatmap.HeatmapType, Heatmap> heatmaps, OkHttpClient okHttpClient)
	{
		if (heatmaps.isEmpty())
		{
			return false;
		}

		String HEATMAP_SITE_API_ENDPOINT = "https://osrsworldheatmap.com/api/upload-csv/";
		try
		{
			// Zip the CSV
			ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
			try (ZipOutputStream zipOutputStream = new ZipOutputStream(byteArrayOutputStream))
			{
				for (Heatmap heatmap : heatmaps.values())
				{
					ZipEntry zipEntry = new ZipEntry(heatmap.getHeatmapType().name() + "_HEATMAP.csv");
					zipOutputStream.putNextEntry(zipEntry);
					OutputStreamWriter osw = new OutputStreamWriter(zipOutputStream);
					heatmap.toCSV(osw);
					osw.flush();
					zipOutputStream.closeEntry();
				}
			}

			// Prepare the request body
			RequestBody requestBody = RequestBody.create(
				MediaType.parse("application/zip"),
				byteArrayOutputStream.toByteArray()
			);

			// Build the request
			Request request = new Request.Builder()
				.url(HEATMAP_SITE_API_ENDPOINT)
				.post(requestBody)
				.build();

			// Execute the request
			try (Response response = okHttpClient.newCall(request).execute())
			{
				if (response.isSuccessful())
				{
					return true;
				}
				else
				{
					log.error("Failed to upload heatmaps: HTTP {} {}", response.code(), response.message());
				}
			}
		}
		catch (IOException e)
		{
			log.error("Error uploading heatmap to {}", HEATMAP_SITE_API_ENDPOINT, e);
		}

		log.error("Failed to upload heatmaps");
		return false;
	}

	/**
	 * Returns the list of discrete coordinates on the path between p0 and p1, as an array of Points
	 * Credit to https:// www.redblobgames.com/grids/line-drawing.html for where I figured out how
	 * to make the following linear interpolation functions
	 *
	 * @param p0 Point A
	 * @param p1 Point B
	 * @return Array of coordinates
	 */
	static Point[] getPointsBetween(Point p0, Point p1) {
		if (p0.equals(p1)) {
			return new Point[]{p1};
		}
		int N = diagonalDistance(p0, p1);
		Point[] points = new Point[N];
		for (int step = 1; step <= N; step++) {
			float t = step / (float) N;
			points[step - 1] = roundPoint(lerp_point(p0, p1, t));
		}
		return points;
	}

	/**
	 * Returns the "diagonal distance" (the maximum of the horizontal and vertical distance) between two points
	 *
	 * @param p0 Point A
	 * @param p1 Point B
	 * @return The diagonal distance
	 */
	static int diagonalDistance(Point p0, Point p1) {
		int dx = Math.abs(p1.getX() - p0.getX());
		int dy = Math.abs(p1.getY() - p0.getY());
		return Math.max(dx, dy);
	}

	/**
	 * Rounds a floating point coordinate to its nearest integer coordinate.
	 *
	 * @param point The point to round
	 * @return Coordinates
	 */
	private static Point roundPoint(float[] point) {
		return new Point(Math.round(point[0]), Math.round(point[1]));
	}

	/**
	 * Returns the floating point 2D coordinate that is t-percent of the way between p0 and p1
	 *
	 * @param p0 Point A
	 * @param p1 Point B
	 * @param t  Percent distance
	 * @return Coordinate that is t% of the way from A to B
	 */
	private static float[] lerp_point(Point p0, Point p1, float t) {
		return new float[]{lerp(p0.getX(), p1.getX(), t), lerp(p0.getY(), p1.getY(), t)};
	}

	/**
	 * Returns the floating point number that is t-percent of the way between p0 and p1.
	 *
	 * @param p0 Point A
	 * @param p1 Point B
	 * @param t  Percent distance
	 * @return Point that is t-percent of the way from A to B
	 */
	private static float lerp(int p0, int p1, float t) {
		return p0 + (p1 - p0) * t;
	}

	/**
	 * Maps a tile value to a hue on the heatmap gradient (green at the minimum, through yellow, to red at the maximum).
	 *
	 * @param tileValue          The tile's value
	 * @param heatmapSensitivity Curve sensitivity; higher values make the gradient more sensitive to low counts
	 * @param minVal             The heatmap's minimum tile value
	 * @param maxVal             The heatmap's maximum tile value
	 * @return The hue, nominally in [0, 1/3]
	 */
	static double heatmapHue(long tileValue, int heatmapSensitivity, long minVal, long maxVal)
	{
		int logBase = 4;
		double logRatio = (float) ((Math.log(tileValue) / Math.log(logBase)) / (Math.log(maxVal + 1 - minVal) / Math.log(logBase)));
		return heatmapHueFromLogRatio(logRatio, heatmapSensitivity);
	}

	/**
	 * The second half of heatmapHue, from the tile value's log ratio (log(value) / log(max range), nominally [0, 1]).
	 * The global heatmaps store this ratio directly.
	 */
	static double heatmapHueFromLogRatio(double logRatio, int heatmapSensitivity)
	{
		double nthRoot = 1 + (heatmapSensitivity - 1.0) / 2;
		double minHue = 1 / 3.0;
		double maxHue = 0.0;
		double currHue = Math.pow(logRatio, 1.0 / nthRoot);
		currHue = (float) (minHue + (currHue * (maxHue - minHue))); // Assign a hue based on normalized step value (values [0, 1] are mapped linearly to hues of [0, 0.333] aka green then yellow, then red)
		return currHue;
	}

	/**
	 * Converts the overlay opacity setting (a percentage) to a 0-255 alpha.
	 */
	static int overlayAlpha(int opacityPercent)
	{
		return Math.max(0, Math.min(255, Math.round(opacityPercent * 2.55f)));
	}

	/**
	 * Returns the fully saturated heatmap colour for a tile value, with the given alpha.
	 * Unlike heatmapHue, the hue is clamped to the gradient so degenerate ranges (e.g. min == max) still draw.
	 */
	static Color heatmapColor(long tileValue, int heatmapSensitivity, long minVal, long maxVal, int alpha)
	{
		return hueToColor(heatmapHue(tileValue, heatmapSensitivity, minVal, maxVal), alpha);
	}

	/**
	 * Like heatmapColor, but from a log ratio (see heatmapHueFromLogRatio).
	 */
	static Color heatmapColorFromLogRatio(double logRatio, int heatmapSensitivity, int alpha)
	{
		return hueToColor(heatmapHueFromLogRatio(logRatio, heatmapSensitivity), alpha);
	}

	private static Color hueToColor(double hue, int alpha)
	{
		if (Double.isNaN(hue))
		{
			hue = 1 / 3.0;
		}
		hue = Math.max(0, Math.min(1 / 3.0, hue));
		int rgb = Color.HSBtoRGB((float) hue, 1, 1) & 0xFFFFFF;
		return new Color((alpha << 24) | rgb, true);
	}

	public static boolean isInOverworld(Point point) {
        return point.getY() < Constants.OVERWORLD_MAX_Y && point.getY() > 2500 && point.getX() >= 1024 && point.getX() < 3960;
    }
}

