/**
 * The open list of the world map heatmap selector (see WorldMapHeatmapSelector), listing None plus the enabled heatmaps.
 * <p>
 * It's an overlay rather than widgets because RuneLite draws world map icons (quest starts, transports etc.) as an
 * overlay after the whole world map interface, so they'd show through widgets. RuneLite only cuts the location
 * selector's own list out of that, so this draws above all widgets instead, using that list's background/border
 * sprites so it looks the same. Clicks are handled as a mouse listener; while it's open, all clicks are consumed so
 * clicking outside it just closes it, like the location list.
 * <p>
 * Mouse events arrive on the AWT thread and rendering happens on the client thread, so the state they share is one
 * immutable snapshot swapped in and out.
 */
@Singleton
class WorldMapHeatmapList extends Overlay implements MouseListener
{
	private static final int GAP = 4;
	private static final int ROW_HEIGHT = 16;
	private static final int PADDING = 6;
	private static final int COLUMN_PADDING = 12;
	private static final Color TEXT_COLOUR = new Color(0xff981f);
	private static final Color TEXT_COLOUR_HOVER = Color.WHITE;
	private static final Color TEXT_COLOUR_SELECTED = new Color(0x00ff00);
	private static final Color FALLBACK_FILL = new Color(0x2e2a24);
	private static final Color FALLBACK_BORDER = new Color(0x0e0e0c);

	private final Client client;
	private final ConfigManager configManager;
	private final WorldHeatmapConfig config;
	private final WorldHeatmapPlugin plugin;
	private final SpriteManager spriteManager;

	/**
	 * Where the list is open and what's in it. Rows are laid out on the first render, since that needs font metrics.
	 */
	private static final class State
	{
		final Rectangle button;
		final Rectangle window;
		final Rectangle box;
		final List<OverlayHeatmap> choices;
		final List<Rectangle> rows;

		State(Rectangle button, Rectangle window, Rectangle box, List<OverlayHeatmap> choices, List<Rectangle> rows)
		{
			this.button = button;
			this.window = window;
			this.box = box;
			this.choices = choices;
			this.rows = rows;
		}
	}

	private volatile State state;
	// Whether the last press was consumed by the list, so the matching release/click are consumed too
	private volatile boolean consumingClick;

	@Inject
	WorldMapHeatmapList(Client client, ConfigManager configManager, WorldHeatmapConfig config, WorldHeatmapPlugin plugin, SpriteManager spriteManager)
	{
		this.client = client;
		this.configManager = configManager;
		this.config = config;
		this.plugin = plugin;
		this.spriteManager = spriteManager;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	boolean isOpen()
	{
		return state != null;
	}

	/**
	 * @param button the selector button's canvas bounds
	 * @param window the world map window's canvas bounds
	 */
	void open(Rectangle button, Rectangle window)
	{
		final List<OverlayHeatmap> choices = new ArrayList<>();
		final OverlayHeatmap current = config.overlayHeatmapType();
		// Global data doesn't depend on which heatmaps this player records
		final boolean global = config.overlayUseGlobalHeatmaps();
		for (OverlayHeatmap choice : OverlayHeatmap.values())
		{
			if (choice == OverlayHeatmap.NONE || choice == current || global || plugin.isHeatmapEnabled(choice.getHeatmapType()))
			{
				choices.add(choice);
			}
		}
		state = new State(button, window, null, choices, null);
	}

	void close()
	{
		state = null;
	}

	/**
	 * Whether the given canvas point is over the open list, e.g. to suppress map tooltips under it.
	 */
	boolean isOverList(int x, int y)
	{
		final State s = state;
		return s != null && s.box != null && s.box.contains(x, y);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		State s = state;
		if (s == null)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeFont());
		final FontMetrics metrics = graphics.getFontMetrics();
		if (s.box == null)
		{
			s = layout(s, metrics);
			// Only publish the layout if the list wasn't closed or reopened meanwhile
			if (state != null && state.box == null && state.button == s.button)
			{
				state = s;
			}
		}

		drawBackground(graphics, s.box);

		final OverlayHeatmap current = config.overlayHeatmapType();
		final Point mouse = client.getMouseCanvasPosition();
		for (int i = 0; i < s.choices.size(); i++)
		{
			final OverlayHeatmap choice = s.choices.get(i);
			final Rectangle row = s.rows.get(i);
			final boolean hovered = mouse != null && row.contains(mouse.getX(), mouse.getY());
			final Color colour = hovered ? TEXT_COLOUR_HOVER : choice == current ? TEXT_COLOUR_SELECTED : TEXT_COLOUR;

			final String text = choice.toString();
			final int textX = row.x;
			final int textY = row.y + (row.height + metrics.getAscent() - metrics.getDescent()) / 2;
			graphics.setColor(Color.BLACK);
			graphics.drawString(text, textX + 1, textY + 1);
			graphics.setColor(colour);
			graphics.drawString(text, textX, textY);
		}
		return null;
	}

	/**
	 * Places the list above the button, in columns if it's too tall for the space above the bar.
	 */
	private static State layout(State s, FontMetrics metrics)
	{
		final int n = s.choices.size();
		final int availableHeight = s.button.y - s.window.y - GAP - 2 * PADDING;
		final int rowsPerColumn = Math.max(1, Math.min(n, availableHeight / ROW_HEIGHT));
		final int columns = (n + rowsPerColumn - 1) / rowsPerColumn;
		int columnWidth = 0;
		for (OverlayHeatmap choice : s.choices)
		{
			columnWidth = Math.max(columnWidth, metrics.stringWidth(choice.toString()));
		}
		columnWidth += COLUMN_PADDING;

		final int width = Math.max(s.button.width, columns * columnWidth + 2 * PADDING);
		final int height = rowsPerColumn * ROW_HEIGHT + 2 * PADDING;
		final int x = Math.max(s.window.x, Math.min(s.button.x, s.window.x + s.window.width - width));
		final int y = Math.max(s.window.y, s.button.y - GAP - height);
		final Rectangle box = new Rectangle(x, y, width, height);

		final List<Rectangle> rows = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			rows.add(new Rectangle(x + PADDING + (i / rowsPerColumn) * columnWidth, y + PADDING + (i % rowsPerColumn) * ROW_HEIGHT, columnWidth, ROW_HEIGHT));
		}
		return new State(s.button, s.window, box, s.choices, rows);
	}

	/**
	 * Draws the location list's background graphic and border pieces, laid out for this box the way the game would.
	 */
	private void drawBackground(Graphics2D graphics, Rectangle box)
	{
		final Widget mapListBox = client.getWidget(InterfaceID.Worldmap.MAPLIST_BOX);
		boolean drewAny = false;
		if (mapListBox != null)
		{
			// Background first so the border pieces draw over it
			drewAny = drawPieces(graphics, box, mapListBox.getStaticChildren());
			drewAny |= drawPieces(graphics, box, mapListBox.getDynamicChildren());
		}
		if (!drewAny)
		{
			graphics.setColor(FALLBACK_FILL);
			graphics.fill(box);
			graphics.setColor(FALLBACK_BORDER);
			graphics.drawRect(box.x, box.y, box.width - 1, box.height - 1);
		}
	}

	private boolean drawPieces(Graphics2D graphics, Rectangle box, Widget[] pieces)
	{
		boolean drewAny = false;
		if (pieces == null)
		{
			return false;
		}
		for (Widget piece : pieces)
		{
			if (piece == null || piece.isSelfHidden())
			{
				continue;
			}

			final Rectangle r = layoutPiece(piece, box);
			if (piece.getType() == WidgetType.GRAPHIC)
			{
				final BufferedImage sprite = piece.getSpriteId() < 0 ? null : spriteManager.getSprite(piece.getSpriteId(), 0);
				if (sprite == null)
				{
					continue;
				}
				if (piece.getSpriteTiling())
				{
					graphics.setPaint(new TexturePaint(sprite, new Rectangle(r.x, r.y, sprite.getWidth(), sprite.getHeight())));
					graphics.fill(r);
				}
				else
				{
					graphics.drawImage(sprite, r.x, r.y, r.width, r.height, null);
				}
				drewAny = true;
			}
			else if (piece.getType() == WidgetType.RECTANGLE)
			{
				final int alpha = 255 - piece.getOpacity();
				graphics.setColor(new Color((alpha << 24) | (piece.getTextColor() & 0xffffff), true));
				if (piece.isFilled())
				{
					graphics.fill(r);
				}
				else
				{
					graphics.drawRect(r.x, r.y, r.width - 1, r.height - 1);
				}
				drewAny = true;
			}
		}
		return drewAny;
	}

	/**
	 * A widget's bounds inside a parent of the given bounds, from its size/position modes (as the client lays them out).
	 */
	private static Rectangle layoutPiece(Widget w, Rectangle parent)
	{
		final int width = size(w.getWidthMode(), w.getOriginalWidth(), parent.width);
		final int height = size(w.getHeightMode(), w.getOriginalHeight(), parent.height);
		final int x = position(w.getXPositionMode(), w.getOriginalX(), parent.width, width);
		final int y = position(w.getYPositionMode(), w.getOriginalY(), parent.height, height);
		return new Rectangle(parent.x + x, parent.y + y, width, height);
	}

	private static int size(int mode, int value, int parentSize)
	{
		switch (mode)
		{
			case WidgetSizeMode.MINUS:
				return parentSize - value;
			case WidgetSizeMode.ABSOLUTE_16384THS:
				return parentSize * value >> 14;
			default:
				return value;
		}
	}

	private static int position(int mode, int value, int parentSize, int size)
	{
		switch (mode)
		{
			case WidgetPositionMode.ABSOLUTE_CENTER:
				return (parentSize - size) / 2 + value;
			case WidgetPositionMode.ABSOLUTE_RIGHT:
				return parentSize - size - value;
			case WidgetPositionMode.LEFT_16384THS:
				return parentSize * value >> 14;
			case WidgetPositionMode.CENTER_16384THS:
				return (parentSize - size) / 2 + (parentSize * value >> 14);
			case WidgetPositionMode.RIGHT_16384THS:
				return parentSize - size - (parentSize * value >> 14);
			default:
				return value;
		}
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		final State s = state;
		if (s == null || s.box == null)
		{
			consumingClick = false;
			return event;
		}

		consumingClick = true;
		event.consume();

		final Point mouse = client.getMouseCanvasPosition();
		if (SwingUtilities.isLeftMouseButton(event) && mouse != null)
		{
			for (int i = 0; i < s.rows.size(); i++)
			{
				if (s.rows.get(i).contains(mouse.getX(), mouse.getY()))
				{
					configManager.setConfiguration(WorldHeatmapConfig.GROUP, "overlayHeatmapType", s.choices.get(i));
					close();
					return event;
				}
			}
		}
		// Anywhere else (including the selector button) closes it; clicks on the box itself are ignored
		if (mouse == null || !s.box.contains(mouse.getX(), mouse.getY()))
		{
			close();
		}
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		if (consumingClick)
		{
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		if (consumingClick)
		{
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent event)
	{
		return event;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent event)
	{
		return event;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		return event;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent event)
	{
		return event;
	}
}

package com.worldheatmap;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.config.ConfigManager;

/**
 * A heatmap selector button in the world map's bottom bar, to the right of the location selector. It's made of
 * dynamic widgets copied from the location selector's own pieces so it matches the game's style. Clicking it opens
 * WorldMapHeatmapList, which sets the overlayHeatmapType config, so it stays in sync with the config panel.
 * Next to it is a globe icon that toggles global heatmaps (the overlayUseGlobalHeatmaps config).
 * Must only be used on the client thread.
 * <p>
 * The bar's layout comes from the world map's clientscripts (the location selector is centred and sized to the widest
 * map name, the zoom/overview buttons are anchored right), so this re-lays itself out every client tick from the real
 * widget positions, and rebuilds itself if the world map is reopened or its children are recreated.
 */
@Singleton
class WorldMapHeatmapSelector
{
	private static final int GAP = 4;
	// Horizontal padding the game uses around the location selector's text (its width is the text width + 52)
	private static final int BUTTON_PADDING = 52;
	private static final int MIN_BUTTON_WIDTH = 80;
	private static final String PREFIX = "Heatmap: ";
	private static final int GLOBE_SIZE = 16;
	// The globe is dimmed while global heatmaps are off (0 = opaque, 255 = invisible)
	private static final int GLOBE_OFF_OPACITY = 150;

	private final Client client;
	private final ConfigManager configManager;
	private final WorldHeatmapConfig config;
	private final WorldMapHeatmapList list;
	private final GlobalHeatmapLoader globalLoader;

	// The bottom bar this was built under, to detect the world map being reopened
	private Widget builtBottom;
	private Widget button;
	private Widget buttonLabel;
	private Widget globeButton;
	private Widget globeIcon;

	@Inject
	WorldMapHeatmapSelector(Client client, ConfigManager configManager, WorldHeatmapConfig config, WorldMapHeatmapList list, GlobalHeatmapLoader globalLoader)
	{
		this.client = client;
		this.configManager = configManager;
		this.config = config;
		this.list = list;
		this.globalLoader = globalLoader;
	}

	void onClientTick()
	{
		final Widget bottom = client.getWidget(InterfaceID.Worldmap.BOTTOM);
		final Widget display = client.getWidget(InterfaceID.Worldmap.MAPLIST_DISPLAY);
		final Widget zoomOut = client.getWidget(InterfaceID.Worldmap.ZOOM_OUT);
		if (!config.showWorldMapOverlay() || bottom == null || display == null || zoomOut == null || bottom.isHidden())
		{
			hide();
			return;
		}

		if (!isBuiltUnder(bottom) && !build(bottom, display))
		{
			return;
		}
		layoutButton(display, zoomOut);
	}

	/**
	 * Hides the selector, e.g. on plugin shutdown. Dynamic widgets can't be deleted individually, and they go away
	 * when the world map is closed anyway.
	 */
	void hide()
	{
		if (button != null && !button.isSelfHidden())
		{
			button.setHidden(true);
		}
		if (globeButton != null && !globeButton.isSelfHidden())
		{
			globeButton.setHidden(true);
		}
		list.close();
	}

	private boolean isBuiltUnder(Widget bottom)
	{
		if (button == null || bottom != builtBottom)
		{
			return false;
		}
		final Widget[] children = bottom.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child == button)
				{
					return true;
				}
			}
		}
		return false;
	}

	private boolean build(Widget bottom, Widget display)
	{
		// The location selector's pieces are created by a script, so wait until they exist
		final Widget[] displayPieces = display.getDynamicChildren();
		if (displayPieces == null || displayPieces.length == 0)
		{
			return false;
		}

		list.close();
		button = bottom.createChild(-1, WidgetType.LAYER);
		button.setOriginalY(display.getOriginalY());
		button.setOriginalHeight(display.getOriginalHeight());
		button.setYPositionMode(display.getYPositionMode());
		button.setHeightMode(display.getHeightMode());
		button.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		button.setWidthMode(WidgetSizeMode.ABSOLUTE);
		button.setHasListener(true);
		button.setAction(0, "Choose");
		button.setName("<col=ff9040>Heatmap</col>");
		button.setOnOpListener((JavaScriptCallback) ev -> toggleList());

		buttonLabel = null;
		for (Widget piece : displayPieces)
		{
			if (piece == null)
			{
				continue;
			}
			Widget copy = copyWidget(piece, button);
			if (buttonLabel == null && piece.getType() == WidgetType.TEXT)
			{
				buttonLabel = copy;
			}
		}
		if (buttonLabel == null)
		{
			buttonLabel = button.createChild(-1, WidgetType.TEXT);
			buttonLabel.setWidthMode(WidgetSizeMode.MINUS);
			buttonLabel.setHeightMode(WidgetSizeMode.MINUS);
			buttonLabel.setXTextAlignment(1);
			buttonLabel.setYTextAlignment(1);
			buttonLabel.setFontId(494);
			buttonLabel.setTextColor(0xff981f);
			buttonLabel.setTextShadowed(true);
		}

		globeButton = bottom.createChild(-1, WidgetType.LAYER);
		globeButton.setOriginalY(display.getOriginalY());
		globeButton.setOriginalHeight(display.getOriginalHeight());
		globeButton.setYPositionMode(display.getYPositionMode());
		globeButton.setHeightMode(display.getHeightMode());
		globeButton.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		globeButton.setWidthMode(WidgetSizeMode.ABSOLUTE);
		globeButton.setOriginalWidth(GLOBE_SIZE);
		globeButton.setHasListener(true);
		globeButton.setName("<col=ff9040>Global heatmaps</col>");
		globeButton.setOnOpListener((JavaScriptCallback) ev -> configManager.setConfiguration(
			WorldHeatmapConfig.GROUP, "overlayUseGlobalHeatmaps", !config.overlayUseGlobalHeatmaps()));

		globeIcon = globeButton.createChild(-1, WidgetType.GRAPHIC);
		globeIcon.setSpriteId(WorldHeatmapSprites.GLOBE.getSpriteId());
		globeIcon.setOriginalWidth(GLOBE_SIZE);
		globeIcon.setOriginalHeight(GLOBE_SIZE);
		globeIcon.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		globeIcon.setYPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);

		builtBottom = bottom;
		return true;
	}

	/**
	 * Copies a widget's look and layout (not its listeners) into a new dynamic child of parent.
	 */
	private static Widget copyWidget(Widget source, Widget parent)
	{
		Widget copy = parent.createChild(-1, source.getType());
		copy.setOriginalX(source.getOriginalX());
		copy.setOriginalY(source.getOriginalY());
		copy.setOriginalWidth(source.getOriginalWidth());
		copy.setOriginalHeight(source.getOriginalHeight());
		copy.setXPositionMode(source.getXPositionMode());
		copy.setYPositionMode(source.getYPositionMode());
		copy.setWidthMode(source.getWidthMode());
		copy.setHeightMode(source.getHeightMode());
		copy.setSpriteId(source.getSpriteId());
		copy.setSpriteTiling(source.getSpriteTiling());
		copy.setFontId(source.getFontId());
		copy.setTextColor(source.getTextColor());
		copy.setTextShadowed(source.getTextShadowed());
		copy.setXTextAlignment(source.getXTextAlignment());
		copy.setYTextAlignment(source.getYTextAlignment());
		copy.setFilled(source.isFilled());
		copy.setOpacity(source.getOpacity());
		copy.setText(source.getText());
		return copy;
	}

	private void layoutButton(Widget display, Widget zoomOut)
	{
		final int x = display.getRelativeX() + display.getWidth() + GAP;
		final int available = zoomOut.getRelativeX() - GAP - x;
		final int globeSpace = GAP + GLOBE_SIZE;

		// In order of preference: full text with the globe, short text with the globe, then without the globe
		// (in which case the label says when global heatmaps are on)
		final String selected = config.overlayHeatmapType().toString();
		String text = null;
		int width = 0;
		boolean showGlobe = false;
		for (int attempt = 0; attempt < 4 && text == null; attempt++)
		{
			showGlobe = attempt < 2;
			final String candidate = (attempt % 2 == 0 ? PREFIX : "") + selected + globalSuffix(showGlobe);
			final int candidateWidth = textWidth(candidate) + BUTTON_PADDING;
			if (candidateWidth + (showGlobe ? globeSpace : 0) <= available)
			{
				text = candidate;
				width = candidateWidth;
			}
		}
		if (text == null)
		{
			// Squeeze the short text into whatever space there is
			showGlobe = false;
			text = selected + globalSuffix(false);
			width = Math.min(textWidth(text) + BUTTON_PADDING, available);
		}

		final boolean fits = width >= MIN_BUTTON_WIDTH;
		if (button.isSelfHidden() == fits)
		{
			button.setHidden(!fits);
		}
		showGlobe &= fits;
		if (globeButton.isSelfHidden() == showGlobe)
		{
			globeButton.setHidden(!showGlobe);
		}
		if (!fits)
		{
			list.close();
			return;
		}

		if (!text.equals(buttonLabel.getText()))
		{
			buttonLabel.setText(text);
		}
		if (button.getOriginalX() != x || button.getOriginalWidth() != width)
		{
			button.setOriginalX(x);
			button.setOriginalWidth(width);
			button.revalidate();
			Widget[] pieces = button.getDynamicChildren();
			if (pieces != null)
			{
				for (Widget piece : pieces)
				{
					if (piece != null)
					{
						piece.revalidate();
					}
				}
			}
			// The list is positioned from the button, so close it rather than leave it floating
			list.close();
		}

		if (showGlobe)
		{
			layoutGlobe(x + width + GAP);
		}
	}

	private void layoutGlobe(int x)
	{
		final boolean global = config.overlayUseGlobalHeatmaps();
		final int opacity = global ? 0 : GLOBE_OFF_OPACITY;
		if (globeIcon.getOpacity() != opacity)
		{
			globeIcon.setOpacity(opacity);
		}
		final String action = global ? "Turn off" : "Turn on";
		final String[] actions = globeButton.getActions();
		if (actions == null || actions.length == 0 || !action.equals(actions[0]))
		{
			globeButton.setAction(0, action);
		}
		if (globeButton.getOriginalX() != x)
		{
			globeButton.setOriginalX(x);
			globeButton.revalidate();
			globeIcon.revalidate();
		}
	}

	/**
	 * In global mode, what the global data is doing (loading etc.), or just that it's global if the globe isn't shown
	 */
	private String globalSuffix(boolean globeShown)
	{
		if (!config.overlayUseGlobalHeatmaps() || config.overlayHeatmapType() == OverlayHeatmap.NONE)
		{
			return "";
		}
		switch (globalLoader.getStatus())
		{
			case LOADING:
				return " (Loading...)";
			case UNAVAILABLE:
				return " (No global data)";
			case ERROR:
				return " (Error)";
			default:
				return globeShown ? "" : " (Global)";
		}
	}

	private int textWidth(String text)
	{
		FontTypeFace font = buttonLabel.getFont();
		return font == null ? text.length() * 6 : font.getTextWidth(text);
	}

	private void toggleList()
	{
		if (list.isOpen())
		{
			list.close();
			return;
		}
		final Widget window = client.getWidget(InterfaceID.Worldmap.WINDOW);
		if (window != null)
		{
			list.open(button.getBounds(), window.getBounds());
		}
	}
}

